    "stddevSampleDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Berechnet die Stichprobenstandardabweichung der Werte und gibt das Ergebnis zur\xFCck. Die Stichprobenabweichung sollte verwendet werden, wenn die angegebenen Werte nur f\xFCr eine Stichprobe oder eine Teilmenge gelten  von Werten f\xFCr eine Grundgesamtheit." } },
    "varianceSampleDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Berechnet die Stichprobenvarianz der Werte und gibt das Ergebnis zur\xFCck. Die Stichprobenvarianz sollte verwendet werden, wenn die bereitgestellten Werte nur f\xFCr eine Stichprobe oder eine Teilmenge von Werten f\xFCr eine zugrunde liegende Grundgesamtheit gelten." } },
    "variancePopDescription": { "t": 0, "b": { "t": 2, "i": [{ "t": 3 }], "s": "Berechnet die Populationsvarianz der Werte und gibt das Ergebnis zur\xFCck. Die Populationsvarianz sollte verwendet werden, wenn die bereitgestellten Werte eine  Wert f\xFCr jeden einzelnen Datensatz in der Grundgesamtheit." } },
